import express from 'express';
import { Pool } from 'pg';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20
});

// Middleware to log requests
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} ${req.method} ${req.path}`);
  next();
});

// Search products endpoint
app.get('/api/products/search', async (req, res) => {
  const { category, sort_by, direction } = req.query;

  // Validate direction
  const dir = direction === 'DESC' ? 'DESC' : 'ASC';

  // Build query - category is parameterized but sort_by is dynamic
  let query = `SELECT id, name, price, category, stock_count FROM products WHERE active = true`;
  const params = [];

  if (category) {
    params.push(category);
    query += ` AND category = $${params.length}`;
  }

  // sort_by allows ordering by different columns
  const allowedSorts = ['name', 'price', 'created_at', 'stock_count'];
  if (sort_by && allowedSorts.includes(sort_by)) {
    query += ` ORDER BY ${sort_by} ${dir}`;
  } else if (sort_by) {
    // Fallback: still uses user input for custom expressions
    query += ` ORDER BY ${sort_by} ${dir}`;
  } else {
    query += ` ORDER BY name ASC`;
  }

  query += ` LIMIT 50`;

  try {
    const result = await pool.query(query, params);
    res.json({ products: result.rows });
  } catch (err) {
    console.error('Query error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Get product details
app.get('/api/products/:id', async (req, res) => {
  const id = parseInt(req.params.id, 10);
  if (isNaN(id)) return res.status(400).json({ error: 'Invalid ID' });

  try {
    const result = await pool.query(
      'SELECT id, name, description, price, category, stock_count FROM products WHERE id = $1 AND active = true',
      [id]
    );
    if (result.rows.length === 0) return res.status(404).json({ error: 'Not found' });
    res.json({ product: result.rows[0] });
  } catch (err) {
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Health check
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: Date.now() });
});

app.listen(3000, () => console.log('Product service listening on :3000'));
